COUNTRY = {
"school-holidays/australia": ("Australia school holidays", "View school holiday periods for Australian states and territories. Dates differ by jurisdiction and year.", "family travel, childcare and leave planning around Australian school breaks"),
"school-holidays/united-kingdom": ("United Kingdom school holidays", "View school holiday periods for supported UK education systems. Dates can vary between nations and local authorities.", "family travel, childcare and leave planning around UK school breaks"),
"school-holidays/united-states": ("United States school holidays", "View general school holiday information for the United States. Exact calendars are set locally and can vary between states and school districts.", "planning around US school breaks while remembering to confirm district dates"),
"school-holidays/new-zealand": ("New Zealand school holidays", "View New Zealand school holiday and term-break periods for the selected year.", "family travel, childcare and leave planning around New Zealand school breaks"),
"school-holidays/canada": ("Canada school holidays", "View general school holiday information for Canada. Exact dates vary by province, territory and school board.", "planning around Canadian school breaks while confirming local board dates"),
"school-holidays/south-africa": ("South Africa school holidays", "View South African school holiday periods for the selected year and calendar where supported.", "family travel, childcare and leave planning around South African school breaks"),
"school-term-dates/australia": ("Australia school term dates", "View term start and finish dates for Australian states and territories.", "family calendars, travel and childcare planning around Australian school terms"),
"school-term-dates/united-kingdom": ("United Kingdom school term dates", "View term-date information for supported UK education systems. Exact dates can vary by nation and local authority.", "family calendars and planning around UK school terms"),
"school-term-dates/united-states": ("United States school term dates", "View general US school term information. Exact start and finish dates are determined locally by districts and schools.", "planning around US school terms while confirming district dates"),
"school-term-dates/new-zealand": ("New Zealand school term dates", "View New Zealand school term start and finish dates for the selected year.", "family calendars, travel and childcare planning around New Zealand school terms"),
}

for slug, (title, intro, use) in COUNTRY.items():
    PAGES[slug] = (f"About {title}", intro, ["Choose the relevant year where available.", "Review the listed term or holiday dates.", "Check any regional notes shown on the page.", "Confirm important bookings or attendance decisions with the relevant education authority or school."], f"Useful for {use}.")

pattern = re.compile(r'<section class="static-content-section container" data-static-seo="true">.*?</section>', re.S)
changed = []
missing = []
for slug, (heading, intro, steps, useful) in PAGES.items():
    path = Path(slug) / "index.html"
    if not path.exists():
        missing.append(str(path)); continue
    html = path.read_text(encoding="utf-8")
    section = f'''<section class="static-content-section container" data-static-seo="true">
  <h2>{heading}</h2>
  <p>{intro}</p>

  <h2>How to use this page</h2>
  <ol>
    {''.join(f'<li>{s}</li>' for s in steps)}
  </ol>

  <h2>When this page is useful</h2>
  <p>{useful}</p>

  <h2>Privacy and accuracy</h2>
  <p>MyCalendarTools keeps these tools lightweight and, wherever practical, performs calculations in your browser. Calendar rules, public holidays, school dates, astronomical data and external forecast data can change or vary by location, so confirm important decisions with the relevant official source.</p>
</section>'''
    new, n = pattern.subn(section, html, count=1)
    if n != 1:
        missing.append(str(path)+" [static SEO block not found]"); continue
    if new != html:
        path.write_text(new, encoding="utf-8")
        changed.append(str(path))

print(f"Changed {len(changed)} pages")
for p in changed: print("CHANGED", p)
if missing:
    print(f"Missing/unmatched {len(missing)}")
    for p in missing: print("MISSING", p)
    raise SystemExit(1)
